// Package geo provides planar geometry helpers for the mapping subsystem.
package geo

import "math"

// Point is a 2D coordinate in the plane.
type Point struct {
	X float64
	Y float64
}

// EuclideanDistance returns the straight-line distance between two points.
func EuclideanDistance(a, b Point) float64 {
	dx := a.X - b.X
	dy := a.Y - b.Y
	return math.Sqrt(dx*dx + dy*dy)
}

/** @module session - Browser session token lifecycle for the web client. */

export interface Session {
  token: string;
  expiresAt: number;
}

export function createSession(token: string, ttlSeconds: number): Session {
  return { token, expiresAt: Date.now() + ttlSeconds * 1000 };
}

export function isSessionExpired(session: Session): boolean {
  return Date.now() > session.expiresAt;
}

/** @module retry - Exponential backoff retry helper for flaky network calls. */

export function backoffDelay(attempt) {
  return Math.min(1000 * 2 ** attempt, 30000);
}

export async function retryWithBackoff(fn, maxAttempts) {
  let lastError;
  for (let attempt = 0; attempt < maxAttempts; attempt += 1) {
    try {
      return await fn();
    } catch (err) {
      lastError = err;
    }
  }
  throw lastError;
}

